package com.atlasiq.twin;
import com.atlasiq.intelligence.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitectureBudgetService {private final ArchitectureDiffService diffs;private final BlastRadiusService blast;public ArchitectureBudgetService(ArchitectureDiffService d,BlastRadiusService b){diffs=d;blast=b;}public Result evaluate(String from,String to,Budget b){ArchitectureDiff d=diffs.compare(from,to);int deps=(int)d.addedEdges().stream().filter(e->e.relationship().contains("depend")||e.relationship().contains("call")).count();int apis=(int)d.addedNodes().stream().filter(n->n.type().contains("api")).count();int maxBlast=d.addedNodes().stream().mapToInt(n->{try{return blast.analyze(to,n.id(),3).affectedNodes().size();}catch(Exception e){return 0;}}).max().orElse(0);List<Violation>v=new ArrayList<>();if(deps>b.maxNewDependencies())v.add(new Violation("new-dependencies",deps,b.maxNewDependencies()));if(apis>b.maxNewPublicApis())v.add(new Violation("new-public-apis",apis,b.maxNewPublicApis()));if(maxBlast>b.maxBlastRadius())v.add(new Violation("blast-radius",maxBlast,b.maxBlastRadius()));return new Result(v.isEmpty(),deps,apis,maxBlast,List.copyOf(v));}public record Budget(int maxNewDependencies,int maxNewPublicApis,int maxBlastRadius){}public record Violation(String metric,int actual,int limit){}public record Result(boolean passed,int newDependencies,int newPublicApis,int maxBlastRadius,List<Violation>violations){}}
